import sys

data = sys.stdin.read().split()
s = data[0]
x = 0
y = 0
for ch in s:
    if ch == 'L':
        x -= 1
    elif ch == 'R':
        x += 1
    elif ch == 'U':
        y += 1
    else:
        y -= 1
print("YES" if x == 0 and y == 0 else "NO")

